L13_1 = "네가 애 구한다고 거기 들어갔다가 건물에 깔려서 타 죽었다면서……!!"
L12_1.m_Talk_KOREA = L13_1
L12_1.m_fTalkTime = 0.03
L13_1 = "あんたが子どもを助けるって、あそこに入ったせいで、瓦礫に埋もれて焼け死んだんでしょう……！！"
L12_1.m_Talk_JPN = L13_1
