L12_1 = "DOCTOR_EXTRA_NULL_NULL"
L11_1.m_CharStrID = L12_1
L12_1 = "아쉽지만, 환자분의 귀와 꼬리에 대해서 현대 의학적으로 드릴 수 있는 조언이 없네요."
L11_1.m_Talk_KOREA = L12_1
L11_1.m_fTalkTime = 0.03
L12_1 = "残念ながら、現代の医学ではあなたの耳と尻尾について何も申し上げることができません。"
L11_1.m_Talk_JPN = L12_1
L12_1 = "I'm sorry, but there is no modern medical advice I can give you regarding your ears and tail."
L11_1.m_Talk_ENG = L12_1
L12_1 = "很遺憾，我無法為你提供有關耳朵和尾巴的醫學建議。"
L11_1.m_Talk_TWN = L12_1
L12_1 = "很遗憾，我无法为你提供有关耳朵和尾巴的医学建议。"
