L17_1 = "DOCTOR_EXTRA_NULL_NULL"
L16_1.m_CharStrID = L17_1
L17_1 = "굉장히 드물지만, 학계에는 그런 경우가 종종 보고되고 있긴 합니다."
L16_1.m_Talk_KOREA = L17_1
L16_1.m_fTalkTime = 0.03
L17_1 = "極稀ではありますが、学会に報告された例がいくつかあります。"
L16_1.m_Talk_JPN = L17_1
L17_1 = "Although it’s extremely rare, such cases are often reported in academia."
L16_1.m_Talk_ENG = L17_1
L17_1 = "儘管你的情況非常罕見，但學術界還是經常有關於此類案例的報導。"
L16_1.m_Talk_TWN = L17_1
L17_1 = "尽管你的情况非常罕见，但学术界还是经常有关于此类案例的报道。"
L16_1.m_Talk_SCN = L17_1
L17_1 = "Although it’s extremely rare, such cases are often reported in academia."
L16_1.m_Talk_DEU = L17_1
L17_1 = "Although it’s extremely rare, such cases are often reported in academia."
L16_1.m_Talk_FRA = L17_1
L17_1 = {}
L18_1 = "YAKSHA_ACT1_STAGE1_START@117#Talk"
