L18_1 = 117
L17_1.m_CutScenProcessKey = L18_1
L17_1.m_CutScenID = 6400104
L17_1.m_CutScenStrID = "YAKSHA_ACT1_STAGE1_START"
L17_1.m_bWaitClick = true
L17_1.m_fWaitTime = 0
L18_1 = "DOCTOR_EXTRA_NULL_NULL"
L17_1.m_CharStrID = L18_1
L18_1 = "갑자기 머리에 뿔이 난다든가, 귀가 동물처럼 변한다든가 하는 경우 말이지요."
L17_1.m_Talk_KOREA = L18_1
L17_1.m_fTalkTime = 0.03
L18_1 = "突然頭に角が生えるとか、耳の形状が動物のように変わるとか……ですね。"
L17_1.m_Talk_JPN = L18_1
L18_1 = "For instance, suddenly growing horns on one's head, or even growing animal-like ears."
L17_1.m_Talk_ENG = L18_1
L18_1 = "例如，頭上突然長出角，或者耳朵變得像動物一樣。"
L17_1.m_Talk_TWN = L18_1
L18_1 = "例如，头上突然长出角，或者耳朵变得像动物一样。"
L17_1.m_Talk_SCN = L18_1
L18_1 = "For instance, suddenly growing horns on one's head, or even growing animal-like ears."
L17_1.m_Talk_DEU = L18_1
L18_1 = "For instance, suddenly growing horns on one's head, or even growing animal-like ears."
