L27_1.m_CharStrID = "MANAGER_YAKSHA_NPC_NULL"
L28_1 = "의도가 좋았다고 해도, 자네는 소방 조직의 규칙을 어기고 민간 재산을 훼손시켰어."
L27_1.m_Talk_KOREA = L28_1
L27_1.m_fTalkTime = 0.03
L28_1 = "意図的ではなかったにせよ、君は消防組織の規定に違反し、民間の財産を毀損した。"
L27_1.m_Talk_JPN = L28_1
L28_1 = "Even though your intentions were good, you still broke fire department regulations and damaged civilian property."
L27_1.m_Talk_ENG = L28_1
L28_1 = "儘管你的初衷是好的，但你不僅違反了消防部門的規定，還損壞了民眾的財產。"
L27_1.m_Talk_TWN = L28_1
L28_1 = "尽管你的初衷是好的，但你不仅违反了消防部门的规定，还损坏了民众的财产。"
L27_1.m_Talk_SCN = L28_1
L28_1 = "Even though your intentions were good, you still broke fire department regulations and damaged civilian property."
L27_1.m_Talk_DEU = L28_1
L28_1 = "Even though your intentions were good, you still broke fire department regulations and damaged civilian property."
L27_1.m_Talk_FRA = L28_1
