L35_1 = "자네에게 닥친 일들이 참 안타깝다고 생각해."
L34_1.m_Talk_KOREA = L35_1
L34_1.m_fTalkTime = 0.03
L35_1 = "君に起きたできごとは、気の毒だと思っている。"
L34_1.m_Talk_JPN = L35_1
L35_1 = "I think it's unfortunate what happened to you."
L34_1.m_Talk_ENG = L35_1
L35_1 = "對於你的遭遇，我覺得很遺憾。"
L34_1.m_Talk_TWN = L35_1
