L8_1 = "RABBIT_YAKSHA_NULL_QM"
L7_1.m_CharStrID = L8_1
L8_1 = "무시무시한 침식체 몸속에서 자라나지만, 이곳저곳 쓸 곳이 많은 광물이거든."
L7_1.m_Talk_KOREA = L8_1
L7_1.m_fTalkTime = 0.03
L8_1 = "恐ろしい侵食体の体内で育つものだけど、何かと使い道のある鉱物なのよ。"
L7_1.m_Talk_JPN = L8_1
L8_1 = "They grow inside those terrifying C.O.s, but it is an ore with numerous applications."
L7_1.m_Talk_ENG = L8_1
L8_1 = "雖然它生長於可怕的侵蝕體體內，但卻是一種用途廣泛的礦物質。"
L7_1.m_Talk_TWN = L8_1
